    const { pathname } = useLocation()
    const check = ROUTES_HEADER_HIDDEN.includes(pathname)
    return (
        <>
            {
                !check &&
                <div className="fixed top-0 left-0 right-0 z-[100] flex items-center justify-between p-[3.2vw] bg-[#fff]"
                    style={{
                        boxShadow: "0 1px .53333vw #64656614"
                    }}
                >
                    21
                </div>
            }

        </>

    )
}

export default MainHeader
